//! Cross-language conformance: bytes produced by the TypeScript compiler
//! (tests/fixtures, regenerated by `npm run fixtures`) must decode here, validate,
//! hash to the stored terms hash, and size the escrow account exactly.

use anchor_lang::prelude::*;
use sha2::{Digest, Sha256};
use solml_escrow::errors::EscrowError as E;
use serde_json::Value;
use solml_escrow::state::*;
use std::str::FromStr;

fn fixture(id: &str) -> (Vec<u8>, String, Value) {
    let dir = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/");
    let hexs = std::fs::read_to_string(format!("{dir}{id}.terms.hex")).unwrap();
    let canonical = std::fs::read_to_string(format!("{dir}{id}.canonical.json")).unwrap();
    let ir: Value = serde_json::from_str(&std::fs::read_to_string(format!("{dir}{id}.ir.json")).unwrap()).unwrap();
    (hex::decode(hexs.trim()).unwrap(), canonical, ir)
}

fn decode(bytes: &[u8]) -> EscrowTerms {
    let mut slice = bytes;
    let t = EscrowTerms::deserialize(&mut slice).expect("terms decode");
    assert!(slice.is_empty(), "trailing bytes after terms");
    t
}

fn pk(v: &Value) -> Pubkey {
    Pubkey::from_str(v.as_str().unwrap()).unwrap()
}

fn u64v(v: &Value) -> u64 {
    v.as_str().unwrap().parse().unwrap()
}

fn check_fixture(id: &str) -> EscrowTerms {
    let (bytes, canonical, ir) = fixture(id);
    let t = decode(&bytes);
    t.validate().expect("compiled terms must pass on-chain validation");
    assert_eq!(t.serialized_len(), bytes.len());
    assert_eq!(t.terms_hash, <[u8; 32]>::from(Sha256::digest(canonical.as_bytes())), "terms hash = sha256(canonical IR)");

    assert_eq!(t.settle_mint, pk(&ir["settle"]["mint"]));
    assert_eq!(t.decimals as u64, ir["settle"]["decimals"].as_u64().unwrap());
    assert_eq!(t.service, pk(&ir["parties"]["service"]));
    assert_eq!(t.client, pk(&ir["parties"]["client"]));
    let gs: Vec<Pubkey> = ir["guarantors"].as_array().unwrap().iter().map(pk).collect();
    assert_eq!(t.guarantors, gs);
    assert_eq!(t.price, u64v(&ir["amounts"]["price"]));
    assert_eq!(t.service_bond, u64v(&ir["amounts"]["serviceBond"]));
    assert_eq!(t.client_bond, u64v(&ir["amounts"]["clientBond"]));
    assert_eq!(t.crank_tip, u64v(&ir["amounts"]["crankTip"]));
    assert_eq!(t.vote_window as u64, ir["windows"]["vote"].as_u64().unwrap());
    let ms = ir["milestones"].as_array().unwrap();
    assert_eq!(t.milestones.len(), ms.len());
    for (m, j) in t.milestones.iter().zip(ms) {
        assert_eq!(m.weight_bps as u64, j["weight"].as_u64().unwrap());
        assert_eq!(m.deadline as u64, j["deadline"].as_u64().unwrap());
        assert_eq!(m.checks.len(), j["checks"].as_array().unwrap().len());
    }

    // Round trip and account sizing.
    let mut out = Vec::new();
    t.serialize(&mut out).unwrap();
    assert_eq!(out, bytes);
    let e = Escrow {
        bump: 255,
        creator: Pubkey::new_unique(),
        state: 0,
        fault: 0,
        client_strike: false,
        dispute: DISPUTE_NONE,
        disputed_by: 0,
        client_funded: 0,
        service_funded: 0,
        protocol_fee: 0,
        guarantor_fee: 0,
        created_at: 0,
        funding_deadline: 0,
        activated_at: 0,
        warranty_end: 0,
        released: 0,
        held: 0,
        tip_pool: 0,
        seat_ok: 0,
        seat_bad: 0,
        milestones: vec![MilestoneState::default(); t.milestones.len()],
        terms: t.clone(),
    };
    let mut acc = Vec::new();
    e.serialize(&mut acc).unwrap();
    assert_eq!(Escrow::space(&t), 8 + acc.len(), "Escrow::space must match the serialized account");
    t
}

#[test]
fn token_launch_fixture_conforms() {
    let t = check_fixture("launch-0042");
    assert_eq!(t.guarantors.len(), 3);
    assert_eq!(t.milestones[0].release, RELEASE_CHECKS);
    assert_eq!(t.milestones[1].release, RELEASE_VOTE);
    assert_eq!(t.milestones[1].on_missed, ON_MISSED_RELEASE, "SSS attribute selector applied");
    assert_eq!(t.service_fault_bps, 7_500, "contract sheet overrides base");
    assert_eq!(t.milestones[0].checks[2].kind, CHECK_MINT_SUPPLY);
    assert!(t.has_vote());
}

#[test]
fn hold_fixture_conforms() {
    let t = check_fixture("pay-dev-0001");
    assert_eq!((t.service_bond, t.client_bond), (0, 0), "hold shorthand carries no bonds");
    assert_eq!(t.milestones.len(), 1);
    assert_eq!(t.milestones[0].release, RELEASE_DEADLINE);
    assert_eq!(t.guarantor_fee_bps, 0);
}

#[test]
fn validate_rejects_tampered_terms() {
    let (bytes, _, _) = fixture("launch-0042");
    let base = decode(&bytes);

    let mut t = base.clone();
    t.milestones[0].weight_bps -= 1;
    assert!(matches!(t.validate(), Err(E::WeightsNot100)), "expected WeightsNot100");

    let mut t = base.clone();
    t.guarantors.push(t.client);
    assert!(matches!(t.validate(), Err(E::SamePartyTwice)), "expected SamePartyTwice");

    let mut t = base.clone();
    t.guarantors.clear();
    assert!(matches!(t.validate(), Err(E::BadRate)), "expected BadRate");
    t.guarantor_fee_bps = 0;
    assert!(matches!(t.validate(), Err(E::VoteWithoutGuarantors)), "expected VoteWithoutGuarantors");

    let mut t = base.clone();
    t.crank_tip = 1;
    assert!(matches!(t.validate(), Err(E::BadCrankTip)), "expected BadCrankTip");

    let mut t = base;
    t.milestones[0].checks.clear();
    assert!(matches!(t.validate(), Err(E::BadChecks)), "expected BadChecks");
}
